using System;
using System.Collections.Generic;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PlayerRunStats", menuName = "Data/PlayerRunStats")]
public class PlayerRunStats : ScriptableObject
{
	[Serializable]
	public class TurnsArea
	{
		public int AreaIndex;

		public List<TurnsBattle> TurnsBattles = new List<TurnsBattle>();

		public float AreaTimer;

		public TurnsArea(int AreaIndex)
		{
			this.AreaIndex = AreaIndex;
		}

		public int AreaTurnCounter()
		{
			int num = 0;
			for (int i = 0; i < TurnsBattles.Count; i++)
			{
				num += TurnsBattles[i].BattleTurnCounter;
			}
			return num;
		}

		public void Execute()
		{
			AreaTimer += Time.unscaledDeltaTime;
		}
	}

	[Serializable]
	public class TurnsBattle
	{
		public int AreaLevelIndex;

		public NodeEnum NodeEnum;

		public string BattlePackage;

		public int BattleTurnCounter;

		public float BattleTimer;

		public bool isBattleEnded;

		public TurnsBattle(int AreaLevelIndex, NodeEnum NodeEnum, string BattlePackage)
		{
			this.AreaLevelIndex = AreaLevelIndex;
			this.NodeEnum = NodeEnum;
			this.BattlePackage = BattlePackage;
			BattleTurnCounter = 0;
			BattleTimer = 0f;
			isBattleEnded = false;
		}

		public void Execute()
		{
			BattleTimer += Time.unscaledDeltaTime;
		}
	}

	[Header("Run Stats")]
	public float RunTotalTime;

	public int TurnCounterTotal;

	public TurnsArea[] TurnsAreas = new TurnsArea[0];

	[SerializeField]
	private bool forcedSeed;

	[Header("Assets")]
	[SerializeField]
	[Expandable]
	private IntReference runSeedIntReference;

	[SerializeField]
	private SaveSystem saveSystem;

	[Header("Events")]
	[SerializeField]
	private StringEvent OnUpdateTurnCounter;

	public TurnsArea CurrentTurnArea => TurnsAreas[ReferenceSingleton<AssetsReference>.Instance.MapHandler.CurrentAreaIndex];

	public TurnsBattle CurrentBattle => CurrentTurnArea.TurnsBattles.Last();

	public List<TurnsBattle> CurrentTurnAreaTurnsBattles => CurrentTurnArea.TurnsBattles;

	public int CurrentAreaIndex => ReferenceSingleton<AssetsReference>.Instance.MapHandler.CurrentAreaIndex;

	public IntReference RunSeedIntReference => runSeedIntReference;

	public void OnResetToStartRunState()
	{
		RunTotalTime = 0f;
		TurnCounterTotal = 0;
		TurnsAreas = new TurnsArea[4];
		for (int i = 0; i < TurnsAreas.Length; i++)
		{
			TurnsAreas[i] = new TurnsArea(i);
		}
	}

	public void GenerateSeed()
	{
		if (!forcedSeed)
		{
			runSeedIntReference.SetValue(RandomUtilities.RandomInt(99999999));
		}
	}

	public int GetSeed()
	{
		return runSeedIntReference.Value;
	}

	public void InitializeTurnsBattle()
	{
		string text = "";
		text = (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.AstreaFirstPhaseDefeatedStartBattleOnAstreaSecondPhase ? "AstreaSecondPhase" : ((ReferenceSingleton<AssetsReference>.Instance.MapHandler.CurrentCustomEventSetup is MeissaBattleCustomEventSetup) ? "MeissaBattle" : ((!(ReferenceSingleton<AssetsReference>.Instance.MapHandler.CurrentCustomEventSetup is CorruptedChestBattleCustomEventSetup)) ? ReferenceSingleton<AssetsReference>.Instance.MapHandler.CurrentNodeData.BattlePackage : "CorruptedChest")));
		TurnsAreas[ReferenceSingleton<AssetsReference>.Instance.MapHandler.CurrentAreaIndex].TurnsBattles.Add(new TurnsBattle(ReferenceSingleton<AssetsReference>.Instance.MapHandler.CurrentAreaLevelIndex, ReferenceSingleton<AssetsReference>.Instance.MapHandler.CurrentNodeData.NodeEnum, text));
	}

	public void EndTurnsBattle()
	{
		CurrentBattle.isBattleEnded = true;
	}

	public void Execute()
	{
		if (ReferenceSingleton<GameStateManager>.Instance.IsOnDeathState)
		{
			return;
		}
		if (Time.unscaledDeltaTime < 1f)
		{
			RunTotalTime += Time.unscaledDeltaTime;
		}
		if (TurnsAreas.Length != 0)
		{
			if (TurnsAreas[ReferenceSingleton<AssetsReference>.Instance.MapHandler.CurrentAreaIndex].TurnsBattles.Count > 0 && !CurrentBattle.isBattleEnded)
			{
				CurrentBattle.Execute();
			}
			CurrentTurnArea.Execute();
		}
	}

	public void IncreaseBattleTurn()
	{
		TurnsAreas[ReferenceSingleton<AssetsReference>.Instance.MapHandler.CurrentAreaIndex].TurnsBattles.Last().BattleTurnCounter++;
		string item = string.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("TurnCounter"), TurnsAreas[ReferenceSingleton<AssetsReference>.Instance.MapHandler.CurrentAreaIndex].TurnsBattles.Last().BattleTurnCounter.ToString());
		OnUpdateTurnCounter.Raise(item);
		TurnCounterTotal++;
	}
}
